import { Component, Input, Output, EventEmitter } from "@angular/core";
import { CommonModule } from "@angular/common";
import { Router } from "@angular/router";
import { FormsModule } from "@angular/forms";

@Component({
  selector: "app-calculadora-modal",
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: "./calculadora-modal.component.html",
  styleUrls: ["./calculadora-modal.component.scss"],
})
export class CalculadoraModalComponent {
  @Input() visible = false;
  @Output() visibleChange = new EventEmitter<boolean>();

  // Transporte
  vehicleType = 'car'; // car, motorcycle, bus
  vehicleKmPerYear = 0;
  vehicleOccupancy = 1; // number of people
  publicTransportKmPerYear = 0;
  homeOfficeDaysPerMonth = 0;

  // Energia
  electricityKwhPerMonth = 0;
  electricitySource = 'grid'; // grid, solar, wind, hydro

  // Alimentação
  dietType = 'omnivore'; // omnivore, vegetarian, vegan
  beefMealsPerWeek = 0;
  dairyServingsPerDay = 0;

  // Consumo
  goodsServicesSpendPerMonth = 0; // in local currency (simplified)
  wasteRecycling = false; // whether they recycle

  // Results
  resultado = 0;
  transporteEmission = 0;
  energiaEmission = 0;
  alimentacaoEmission = 0;
  consumoEmission = 0;
  feedback = "";
  cor = "";

  constructor(private router: Router) {}

  calcular() {
    // Calculate CO2 emissions using 2026 emission factors (simplified for educational purposes)

    // Transporte
    // Base factors: kg CO2 per km
    let vehicleFactor = 0;
    switch (this.vehicleType) {
      case 'car':
        vehicleFactor = 0.12; // average car
        break;
      case 'motorcycle':
        vehicleFactor = 0.08;
        break;
      case 'bus':
        vehicleFactor = 0.05; // per passenger when full
        break;
    }
    // Adjust for occupancy (more people = less per person)
    const vehicleEmission = (this.vehicleKmPerYear * vehicleFactor) / Math.max(1, this.vehicleOccupancy);

    // Public transport (much lower emission)
    const publicTransportEmission = this.publicTransportKmPerYear * 0.03;

    // Home office reduces commuting (simplified: 1 day home office = 20% less commuting)
    const homeOfficeReduction = this.homeOfficeDaysPerMonth * 0.2 * (this.vehicleKmPerYear / 12) * vehicleFactor / Math.max(1, this.vehicleOccupancy);

    this.transporteEmission = Math.max(0, vehicleEmission + publicTransportEmission - homeOfficeReduction) / 1000; // convert to tCO2

    // Energia
    let energyFactor = 0.08; // average grid kg CO2 per kWh (2026)
    switch (this.electricitySource) {
      case 'solar':
        energyFactor = 0.02;
        break;
      case 'wind':
        energyFactor = 0.01;
        break;
      case 'hydro':
        energyFactor = 0.015;
        break;
      case 'grid':
      default:
        energyFactor = 0.08;
    }
    this.energiaEmission = (this.electricityKwhPerMonth * 12 * energyFactor) / 1000; // tCO2

    // Alimentação
    let dietBase = 1.5; // base tCO2 for vegetarian/vegan
    switch (this.dietType) {
      case 'omnivore':
        dietBase = 2.5;
        break;
      case 'vegetarian':
        dietBase = 1.5;
        break;
      case 'vegan':
        dietBase = 0.8;
        break;
    }
    // Add beef impact (high emission food)
    const beefEmission = this.beefMealsPerWeek * 0.05 * 52; // weekly to yearly
    // Add dairy impact
    const dairyEmission = this.dairyServingsPerDay * 0.002 * 365; // daily to yearly
    this.alimentacaoEmission = dietBase + (beefEmission + dairyEmission) / 1000; // convert kg to t

    // Consumo (simplified based on spending)
    // Assuming 0.4 kg CO2 per dollar spent (simplified)
    this.consumoEmission = (this.goodsServicesSpendPerMonth * 12 * 0.4) / 1000; // tCO2

    // Adjust for recycling (reduces emissions by ~20%)
    if (this.wasteRecycling) {
      this.consumoEmission *= 0.8;
    }

    // Total
    this.resultado = this.transporteEmission + this.energiaEmission + this.alimentacaoEmission + this.consumoEmission;
    this.setFeedback();
  }

  setFeedback() {
    if (this.resultado < 1.5) {
      this.feedback = "PARABÉNS!";
      this.cor = "#00a86b";
    } else if (this.resultado < 2.5) {
      this.feedback = "ÓTIMO!";
      this.cor = "#7cb342";
    } else if (this.resultado < 4.0) {
      this.feedback = "MÉDIA";
      this.cor = "#fbc02d";
    } else if (this.resultado < 6.0) {
      this.feedback = "ALERTA";
      this.cor = "#f57c00";
    } else {
      this.feedback = "CRÍTICO";
      this.cor = "#d32f2f";
    }
  }

  fechar() {
    this.visible = false;
    this.visibleChange.emit(this.visible);
  }

  verAcoes() {
    this.fechar();
    this.router.navigate(["/acoes"]);
  }
}
